% =========================================================================
% 車內生命徵象數位孿生系統：Sim2Real 資料生成、閉環控制與 ML 狀態分類
% =========================================================================

num_samples = 150; % 生成 150 組測試情境
fps = 100;         % 雷達幀率 100 Hz
base_duration = 10;% 預設基礎觀測時間 10 秒

% 準備陣列來儲存機器學習的「特徵 (Features)」與「標籤 (Labels)」
features = zeros(num_samples, 2); % 兩個特徵：[呼吸頻率, 心跳頻率]
labels = strings(num_samples, 1); % 標籤：'Normal', 'Stress', 'Baby(CPD)'

disp('啟動數位孿生引擎，開始自動生成虛擬場景資料...'); %[output:37d4b03a]

for i = 1:num_samples %[output:group:04a348be]
    % -----------------------------------------------------------
    % 實作一：Sim2Real 場景生成 (隨機決定乘客狀態)
    % -----------------------------------------------------------
    rand_state = randi(3); % 1: 正常, 2: 急促(壓力/疲勞), 3: 嬰兒遺留(CPD)
    
    if rand_state == 1
        % [狀態 1] 正常成人：呼吸 0.25Hz(振幅5mm), 心跳 1.2Hz(振幅0.5mm)
        fr = 0.25 + 0.05*randn; Ar = 0.005;
        fh = 1.20 + 0.10*randn; Ah = 0.0005;
        labels(i) = 'Normal';
    elseif rand_state == 2
        % [狀態 2] 壓力/急促：呼吸 0.5Hz(振幅4mm), 心跳 1.8Hz(振幅0.6mm)
        fr = 0.50 + 0.05*randn; Ar = 0.004;
        fh = 1.80 + 0.15*randn; Ah = 0.0006;
        labels(i) = 'Stress';
    else
        % [狀態 3] 嬰兒遺留：呼吸 0.4Hz(振幅極小 1.5mm), 心跳 2.2Hz(振幅0.2mm)
        fr = 0.40 + 0.05*randn; Ar = 0.0015;
        fh = 2.20 + 0.20*randn; Ah = 0.0002;
        labels(i) = 'Baby(CPD)';
    end
    
    % 加入隨機的車體震動與環境雜訊
    noise_level = 0.0005 + 0.001 * rand; % 隨機決定這次環境有多吵
    
    % -----------------------------------------------------------
    % 實作三：閉環回饋控制 (Closed-Loop Feedback)
    % -----------------------------------------------------------
    % 系統自我評估：如果發現環境雜訊太大 (品質過低)，自動觸發動態校正
    current_duration = base_duration;
    if noise_level > 0.0012
        % 觸發計畫書 6.4 節：模型不確定度過高，延長觀測窗
        fprintf('[閉環控制觸發] 樣本 %d 雜訊過高，自動將觀測時間從 10 秒延長至 15 秒。\n', i); %[output:2b4c3e60]
        current_duration = 15; 
    end
    
    % 根據決定好的時間長度生成物理位移模型
    timeVec = (0:(current_duration*fps)-1) / fps;
    random_noise = noise_level * randn(1, length(timeVec));
    car_sway = 0.01 * sin(2 * pi * 0.1 * timeVec); % 低頻車體晃動
    
    % 數位孿生合成總位移 (物理模型 + 雜訊)
    displacement = Ar*sin(2*pi*fr*timeVec) + Ah*sin(2*pi*fh*timeVec) + car_sway + random_noise;
    
    % 將位移轉換為雷達相位並進行濾波 (模擬 DSP 處理)
    noisy_phase = (4 * pi * displacement) / (3e8/60e9); 
    breathing_signal = bandpass(noisy_phase, [0.15 0.7], fps);
    heartbeat_signal = bandpass(noisy_phase, [0.8 2.5], fps);
    
    % -----------------------------------------------------------
    % 實作二 (前置作業)：特徵提取 (Feature Extraction)
    % -----------------------------------------------------------
    % 利用 FFT 找出波形中能量最強的主頻率，作為機器學習的特徵
    [pxx_b, f_b] = pwelch(breathing_signal, [], [], [], fps);
    [~, max_idx_b] = max(pxx_b);
    extracted_br = f_b(max_idx_b); % 算出的呼吸頻率
    
    [pxx_h, f_h] = pwelch(heartbeat_signal, [], [], [], fps);
    [~, max_idx_h] = max(pxx_h);
    extracted_hr = f_h(max_idx_h); % 算出的心跳頻率
    
    % 存入特徵矩陣
    features(i, :) = [extracted_br, extracted_hr];
end %[output:group:04a348be]

disp('資料生成與特徵提取完成！準備進入機器學習分類階段...'); %[output:520c85a6]

% -----------------------------------------------------------
% 實作二：機器學習狀態診斷 (隨機森林 Random Forest 分類器)
% -----------------------------------------------------------
% 1. 先將陣列資料轉為 Table 格式，並正式命名欄位 (這步必須最先做)
dataset = table(features(:,1), features(:,2), categorical(labels), ...
    'VariableNames', {'BreathRate_Hz', 'HeartRate_Hz', 'PassengerState'});

% 2. 訓練機器學習模型 (使用分類集成樹 Random Forest)
disp('開始訓練分類器...'); %[output:8e8f570d]
Mdl = fitcensemble(dataset, 'PassengerState');
disp('分類器訓練完成。'); %[output:22bc4ace]

% 3. 進行預測
predicted_labels = predict(Mdl, dataset);
disp('預測完成。'); %[output:5ca3fa02]

% 4. 繪製成果圖表
figure('Position', [100, 100, 800, 400]); %[output:47fcb8df]

subplot(1,2,1); %[output:47fcb8df]
% 繪製特徵散佈圖 (Feature Space)
gscatter(dataset.BreathRate_Hz, dataset.HeartRate_Hz, dataset.PassengerState, 'rgb', 'osd'); %[output:47fcb8df]
xlabel('Extracted Breathing Frequency (Hz)'); %[output:47fcb8df]
ylabel('Extracted Heartbeat Frequency (Hz)'); %[output:47fcb8df]
title('Digital Twin Feature Space'); %[output:47fcb8df]
grid on; %[output:47fcb8df]

subplot(1,2,2); %[output:47fcb8df]
% 繪製分類混淆矩陣 (Confusion Matrix)
confusionchart(dataset.PassengerState, predicted_labels); %[output:47fcb8df]
title('ML Classification Confusion Matrix'); %[output:47fcb8df]

